// Generates Metro-compatible static requires only for MP3s which really exist.
// Re-run after adding ElevenLabs files; the generated file is safe to commit.
const fs = require('node:fs');
const path = require('node:path');
const root = path.resolve(__dirname, '..');
const folder = path.join(root, 'assets', 'scorpion-sfx');
const destination = path.join(root, 'mobile', 'constants', 'scorpionAudioSources.js');
const names = ['shuffle_cards', 'deal_card', 'flip_card', 'courtyard_ambience'];
const found = names.filter(id => fs.existsSync(path.join(folder, id + '.mp3')));
const body = [
  '// Generated by node scripts/prepare-scorpion-audio.js. Do not edit by hand.',
  'export const SCORPION_AUDIO_SOURCES = Object.freeze({',
  ...found.map(id => `  ${id}: require('../../assets/scorpion-sfx/${id}.mp3'),`),
  '});',
  '',
].join('\n');
fs.mkdirSync(folder, { recursive: true });
fs.writeFileSync(destination, body);
console.log('Scorpion SFX loaded: ' + (found.join(', ') || 'none yet (waiting for ElevenLabs audio)'));
console.log('Expected files: ' + names.filter(n=>!found.includes(n)).map(n=>n+'.mp3').join(', '));
